import React, { useState, useEffect } from "react";
import { axiosGet } from "../apiService";

const instruments = [
  { key: "gold", label: "Gold", region: "MCX", source: "TradingView" },
  { key: "nifty50", label: "Nifty 50", region: "India", source: "TradingView" },
  { key: "bankNifty", label: "Bank Nifty", region: "India", source: "TradingView" },
  { key: "sensex", label: "Sensex", region: "India", source: "TradingView" },
];

export default function MarketSnapshot() {
  const [marketData, setMarketData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchMarketData = async () => {
      try {
        setLoading(true);
        setError(null);
        const data = await axiosGet("market/snapshot");
        setMarketData(data || null);
      } catch (err) {
        console.error("Failed to fetch market data:", err);
        setError("Exchange rate feed is temporarily unavailable.");
      } finally {
        setLoading(false);
      }
    };

    fetchMarketData();
    const interval = setInterval(fetchMarketData, 300000);
    return () => clearInterval(interval);
  }, []);

  const formatCurrency = (value) => {
    if (value === null || value === undefined) return "—";
    return Number(value).toLocaleString("en-IN", {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    });
  };

  const formatRate = (value) => {
    if (value === null || value === undefined) return "—";
    return Number(value).toLocaleString("en-IN", {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    });
  };

  const quote = marketData?.usdInr;
  const usdPrice = quote?.status === "Available" ? formatRate(quote.currentPrice) : "—";

  const rows = instruments.map((inst) => {
    const data = marketData?.[inst.key];
    const hasData = data?.status === "Available";
    const value = hasData ? formatCurrency(data.currentPrice) : "—";
    const changeText = hasData && data.change !== null && data.change !== undefined
      ? `${data.change >= 0 ? "+" : ""}${formatCurrency(data.change)} (${data.changePercent >= 0 ? "+" : ""}${formatCurrency(data.changePercent)}%)`
      : "—";

    const changePercentValue = hasData ? Number.parseFloat((changeText || "").split("(")[1]?.replace("%)", "")) : NaN;
    const trendClass = !hasData || !Number.isFinite(changePercentValue)
      ? "neutral"
      : changePercentValue >= 0
        ? "up"
        : "down";

    return { ...inst, value, changeText, trendClass, hasData };
  });

  return (
    <div className="market-summary-shell">
      <div className="market-summary-card market-summary-rate">
        <div className="summary-heading">USD / INR</div>
        <div className="summary-rate">₹{usdPrice}</div>
        <div className="summary-subtitle">
          {error ? "Feed unavailable" : loading ? "Updating..." : "ExchangeRate-API"}
        </div>
      </div>

      <div className="market-summary-card market-summary-ticker">
        <div className="ticker-header">MARKET SNAPSHOT</div>
        <div className="ticker-grid">
          {rows.map((row) => (
            <div key={row.key} className="ticker-row">
              <span className="ticker-name">{row.label}</span>
              <span className="ticker-value">{row.value}</span>
              <span className={`ticker-change ${row.trendClass}`}>
                {row.hasData ? row.changeText : "—"}
              </span>
            </div>
          ))}
        </div>
        <div className="ticker-footer">Powered by TradingView</div>
      </div>
    </div>
  );
}
